const AGENT_CHAT_EMPTY_TITLE = 'New chat';
const AGENT_CHAT_PERSISTED_THREAD_LIMIT = 32;
const AGENT_CHAT_PERSISTED_MESSAGE_LIMIT = 80;

const WORKSPACE_MODE_LOCAL_MOCK = 'local_mock';
const WORKSPACE_MODE_SHOTGRID = 'shotgrid';
const WORKSPACE_SELECTOR_LOCAL_MOCK = '__workspace_local_mock__';
const WORKSPACE_SELECTOR_SHOTGRID_PREFIX = '__workspace_shotgrid__:';
const SHOTGRID_AUTH_POLICY_VALUES = new Set(['user_only', 'hybrid_explicit', 'script_only']);

function cloneAgentCatalog(source = FALLBACK_AGENT_CATALOG) {
  return JSON.parse(JSON.stringify(source));
}

function normalizeAgentProviderId(value) {
  const normalized = String(value || '').trim().toLowerCase();
  if (normalized === 'claude') return 'anthropic';
  return DEFAULT_AGENT_PROVIDER_META[normalized] ? normalized : '';
}

function normalizeAgentModelRef(value, fallback = 'codex/default') {
  const raw = String(value || '').trim();
  if (!raw) return fallback;
  if (!raw.includes('/')) {
    const providerId = normalizeAgentProviderId(raw);
    if (!providerId) return fallback;
    const providerEntry = getAgentProviderEntry(providerId, { catalog: FALLBACK_AGENT_CATALOG });
    return providerEntry?.default_model_ref || fallback;
  }
  const [providerRaw, ...modelParts] = raw.split('/');
  const providerId = normalizeAgentProviderId(providerRaw);
  const modelId = modelParts.join('/').trim();
  if (!providerId || !modelId) return fallback;
  return `${providerId}/${modelId}`;
}

function agentProviderMeta(value, options = {}) {
  const providerId = normalizeAgentProviderId(value);
  const catalog = options.catalog && typeof options.catalog === 'object' ? options.catalog : state.agentCatalog;
  const providerEntry = Array.isArray(catalog?.providers)
    ? catalog.providers.find((entry) => normalizeAgentProviderId(entry?.provider_id) === providerId)
    : null;
  const fallback = DEFAULT_AGENT_PROVIDER_META[providerId] || DEFAULT_AGENT_PROVIDER_META.codex;
  return {
    key: providerId || fallback.provider_id,
    label: String(providerEntry?.label || fallback.label || providerId || 'Agent'),
    logoPath: String(providerEntry?.logo_path || fallback.logo_path || '').trim(),
    logoAlt: String(providerEntry?.logo_alt || fallback.logo_alt || `${fallback.label} logo` || 'Agent logo')
  };
}

function getAgentProviderEntry(providerId, options = {}) {
  const normalized = normalizeAgentProviderId(providerId);
  const catalog = options.catalog && typeof options.catalog === 'object' ? options.catalog : state.agentCatalog;
  const provider = Array.isArray(catalog?.providers)
    ? catalog.providers.find((entry) => normalizeAgentProviderId(entry?.provider_id) === normalized)
    : null;
  if (provider) return provider;
  const fallback = DEFAULT_AGENT_PROVIDER_META[normalized] || DEFAULT_AGENT_PROVIDER_META.codex;
  return {
    provider_id: fallback.provider_id,
    label: fallback.label,
    aliases: [...(fallback.aliases || [])],
    logo_path: fallback.logo_path || '',
    auth_modes: [],
    capabilities: { structured_output_mode: 'json_object_text', supports_reasoning_effort: true, supports_fallback: true, supports_tool_planning: true },
    default_model_ref: fallback.provider_id === 'openai'
      ? 'openai/gpt-4o-mini'
      : fallback.provider_id === 'anthropic'
        ? 'anthropic/claude-3-5-sonnet-20241022'
        : fallback.provider_id === 'gemini'
          ? 'gemini/gemini-2.0-flash'
          : 'codex/default',
    connection: null
  };
}

function getAgentModelCatalog(options = {}) {
  const catalog = options.catalog && typeof options.catalog === 'object' ? options.catalog : state.agentCatalog;
  return Array.isArray(catalog?.models) && catalog.models.length > 0
    ? catalog.models
    : cloneAgentCatalog(FALLBACK_AGENT_CATALOG).models;
}

function getAgentModelEntry(modelRef, options = {}) {
  const normalized = normalizeAgentModelRef(modelRef, '');
  const models = getAgentModelCatalog(options);
  const found = models.find((entry) => normalizeAgentModelRef(entry?.model_ref, '') === normalized);
  if (found) return found;
  if (!normalized) return models[0] || null;
  const [providerId, modelId = 'default'] = normalized.split('/');
  return {
    model_ref: normalized,
    provider_id: normalizeAgentProviderId(providerId),
    model_id: modelId,
    label: modelId || normalized,
    description: '',
    capabilities: { supports_reasoning_effort: true },
    enabled: true
  };
}

function getAgentDefaultModelRef(providerId) {
  return getAgentProviderEntry(providerId)?.default_model_ref
    || state.agentCatalog?.defaults?.default_model
    || 'codex/default';
}

function applyAgentCatalog(catalogPayload) {
  if (!catalogPayload || typeof catalogPayload !== 'object') {
    state.agentCatalog = cloneAgentCatalog();
    return state.agentCatalog;
  }
  const next = cloneAgentCatalog();
  if (Array.isArray(catalogPayload.providers) && catalogPayload.providers.length > 0) {
    next.providers = catalogPayload.providers.map((entry) => {
      const providerId = normalizeAgentProviderId(entry?.provider_id || entry?.provider);
      const fallback = DEFAULT_AGENT_PROVIDER_META[providerId] || DEFAULT_AGENT_PROVIDER_META.codex;
      return {
        provider_id: providerId || fallback.provider_id,
        label: String(entry?.label || fallback.label),
        aliases: Array.isArray(entry?.aliases) ? entry.aliases.map((item) => String(item || '').trim().toLowerCase()).filter(Boolean) : [...(fallback.aliases || [])],
        logo_path: String(entry?.logo_path || fallback.logo_path || '').trim(),
        auth_modes: Array.isArray(entry?.auth_modes) ? entry.auth_modes : [],
        capabilities: entry?.capabilities && typeof entry.capabilities === 'object' ? entry.capabilities : { structured_output_mode: 'json_object_text', supports_reasoning_effort: true, supports_fallback: true, supports_tool_planning: true },
        model_discovery: entry?.model_discovery && typeof entry.model_discovery === 'object' ? entry.model_discovery : {},
        default_model_ref: normalizeAgentModelRef(entry?.default_model_ref || fallback.default_model_ref || '', fallback.provider_id === 'openai'
          ? 'openai/gpt-4o-mini'
          : fallback.provider_id === 'anthropic'
            ? 'anthropic/claude-3-5-sonnet-20241022'
            : fallback.provider_id === 'gemini'
              ? 'gemini/gemini-2.0-flash'
              : 'codex/default'),
        connection: entry?.connection && typeof entry.connection === 'object' ? entry.connection : null
      };
    });
  }
  if (Array.isArray(catalogPayload.models) && catalogPayload.models.length > 0) {
    next.models = catalogPayload.models
      .map((entry) => {
        const modelRef = normalizeAgentModelRef(entry?.model_ref, '');
        if (!modelRef) return null;
        const providerId = normalizeAgentProviderId(entry?.provider_id || modelRef.split('/')[0]);
        return {
          model_ref: modelRef,
          provider_id: providerId,
          model_id: String(entry?.model_id || modelRef.split('/').slice(1).join('/') || 'default'),
          label: String(entry?.label || modelRef.split('/').slice(1).join('/') || modelRef),
          description: String(entry?.description || ''),
          capabilities: entry?.capabilities && typeof entry.capabilities === 'object' ? entry.capabilities : { supports_reasoning_effort: true },
          enabled: entry?.enabled !== false,
          source: String(entry?.source || ''),
          is_default: entry?.is_default === true,
          metadata: entry?.metadata && typeof entry.metadata === 'object' ? entry.metadata : {}
        };
      })
      .filter(Boolean);
  }
  const defaults = catalogPayload.defaults && typeof catalogPayload.defaults === 'object' ? catalogPayload.defaults : {};
  next.defaults = {
    default_model: normalizeAgentModelRef(defaults.default_model || defaults.defaultModel || next.defaults.default_model),
    default_model_by_project: defaults.default_model_by_project && typeof defaults.default_model_by_project === 'object'
      ? Object.fromEntries(Object.entries(defaults.default_model_by_project).map(([scope, ref]) => [String(scope || ''), normalizeAgentModelRef(ref)]).filter(([scope, ref]) => scope && ref))
      : {},
    fallbacks: Array.isArray(defaults.fallbacks)
      ? defaults.fallbacks.map((item) => normalizeAgentModelRef(item, '')).filter(Boolean)
      : []
  };
  next.connections = Array.isArray(catalogPayload.connections) ? catalogPayload.connections : next.connections;
  state.agentCatalog = next;
  const availableModels = getAgentAvailableModelCatalog({ catalog: next });
  const availableRefs = new Set(
    availableModels
      .map((entry) => normalizeAgentModelRef(entry?.model_ref, ''))
      .filter(Boolean)
  );
  const currentModelRef = normalizeAgentModelRef(state.agentChatUi.modelRef, '');
  state.agentChatUi.modelRef = availableRefs.has(currentModelRef)
    ? currentModelRef
    : (getAgentPreferredModelRef({ catalog: next, models: availableModels }) || '');
  return next;
}

function isAgentProviderConnected(providerOrId, options = {}) {
  const provider = providerOrId && typeof providerOrId === 'object'
    ? providerOrId
    : getAgentProviderEntry(providerOrId, options);
  return String(provider?.connection?.status || '').trim().toLowerCase() === 'connected';
}

function getConnectedAgentProviders(options = {}) {
  const catalog = options.catalog && typeof options.catalog === 'object' ? options.catalog : state.agentCatalog;
  const providers = Array.isArray(catalog?.providers) ? catalog.providers : [];
  return providers.filter((provider) => isAgentProviderConnected(provider, { catalog }));
}

function isAgentResolvedAliasModel(entry) {
  const modelId = String(entry?.model_id || '').trim().toLowerCase();
  if (modelId !== 'default') return false;
  const metadata = entry?.metadata && typeof entry.metadata === 'object' ? entry.metadata : {};
  return Boolean(normalizeAgentModelRef(metadata?.resolved_model_ref, ''));
}

function getAgentAvailableModelCatalog(options = {}) {
  const catalog = options.catalog && typeof options.catalog === 'object' ? options.catalog : state.agentCatalog;
  const connectedProviderIds = new Set(
    getConnectedAgentProviders({ catalog })
      .map((provider) => normalizeAgentProviderId(provider?.provider_id || provider?.provider))
      .filter(Boolean)
  );
  const models = getAgentModelCatalog({ catalog }).filter((entry) => {
    const providerId = normalizeAgentProviderId(entry?.provider_id || entry?.provider);
    return entry?.enabled !== false && providerId && connectedProviderIds.has(providerId);
  });
  const visibleSiblingCounts = new Map();
  models.forEach((entry) => {
    const providerId = normalizeAgentProviderId(entry?.provider_id || entry?.provider);
    if (!providerId || isAgentResolvedAliasModel(entry)) return;
    visibleSiblingCounts.set(providerId, (visibleSiblingCounts.get(providerId) || 0) + 1);
  });
  return models.filter((entry) => {
    if (!isAgentResolvedAliasModel(entry)) return true;
    const providerId = normalizeAgentProviderId(entry?.provider_id || entry?.provider);
    return (visibleSiblingCounts.get(providerId) || 0) === 0;
  });
}

function compareAgentModelEntries(a, b, options = {}) {
  const catalog = options.catalog && typeof options.catalog === 'object' ? options.catalog : state.agentCatalog;
  const preferredModelRef = normalizeAgentModelRef(options.preferredModelRef, '');
  const aRef = normalizeAgentModelRef(a?.model_ref, '');
  const bRef = normalizeAgentModelRef(b?.model_ref, '');
  const aIsPreferred = preferredModelRef && aRef === preferredModelRef;
  const bIsPreferred = preferredModelRef && bRef === preferredModelRef;
  if (aIsPreferred !== bIsPreferred) return aIsPreferred ? -1 : 1;
  const aProviderId = normalizeAgentProviderId(a?.provider_id || aRef.split('/')[0]);
  const bProviderId = normalizeAgentProviderId(b?.provider_id || bRef.split('/')[0]);
  const aProviderDefault = aRef && aRef === normalizeAgentModelRef(getAgentProviderEntry(aProviderId, { catalog })?.default_model_ref, '');
  const bProviderDefault = bRef && bRef === normalizeAgentModelRef(getAgentProviderEntry(bProviderId, { catalog })?.default_model_ref, '');
  if (aProviderDefault !== bProviderDefault) return aProviderDefault ? -1 : 1;
  if ((a?.is_default === true) !== (b?.is_default === true)) return a?.is_default === true ? -1 : 1;
  const aSortRank = Number(a?.metadata?.sort_rank);
  const bSortRank = Number(b?.metadata?.sort_rank);
  const aHasSortRank = Number.isFinite(aSortRank);
  const bHasSortRank = Number.isFinite(bSortRank);
  if (aHasSortRank || bHasSortRank) {
    const resolvedARank = aHasSortRank ? aSortRank : Number.MAX_SAFE_INTEGER;
    const resolvedBRank = bHasSortRank ? bSortRank : Number.MAX_SAFE_INTEGER;
    if (resolvedARank !== resolvedBRank) return resolvedARank - resolvedBRank;
  }
  const aProviderLabel = agentProviderMeta(aProviderId, { catalog }).label;
  const bProviderLabel = agentProviderMeta(bProviderId, { catalog }).label;
  const providerCompare = aProviderLabel.localeCompare(bProviderLabel, undefined, { sensitivity: 'base' });
  if (providerCompare !== 0) return providerCompare;
  const aLabel = String(a?.label || a?.model_id || aRef).trim() || aRef;
  const bLabel = String(b?.label || b?.model_id || bRef).trim() || bRef;
  return aLabel.localeCompare(bLabel, undefined, { sensitivity: 'base' });
}

function getAgentPreferredModelRef(options = {}) {
  const catalog = options.catalog && typeof options.catalog === 'object' ? options.catalog : state.agentCatalog;
  const models = Array.isArray(options.models) ? options.models : getAgentAvailableModelCatalog({ catalog });
  if (!models.length) return '';
  const availableRefs = new Set(
    models
      .map((entry) => normalizeAgentModelRef(entry?.model_ref, ''))
      .filter(Boolean)
  );
  const projectScope = typeof options.projectScope === 'string' && options.projectScope.trim()
    ? options.projectScope.trim()
    : currentAgentProjectScope();
  const projectDefaults = appSettings.agentSettings?.defaultModelByProject && typeof appSettings.agentSettings.defaultModelByProject === 'object'
    ? appSettings.agentSettings.defaultModelByProject
    : {};
  const projectDefaultRef = normalizeAgentModelRef(projectDefaults[projectScope], '');
  if (availableRefs.has(projectDefaultRef)) return projectDefaultRef;
  const globalDefaultRef = normalizeAgentModelRef(appSettings.agentSettings?.defaultModel, '');
  if (availableRefs.has(globalDefaultRef)) return globalDefaultRef;
  const catalogDefaultRef = normalizeAgentModelRef(catalog?.defaults?.default_model, '');
  if (availableRefs.has(catalogDefaultRef)) return catalogDefaultRef;
  const ordered = [...models].sort((a, b) => compareAgentModelEntries(a, b, { catalog }));
  return normalizeAgentModelRef(ordered[0]?.model_ref, '');
}

function getOrderedAgentAvailableModels(options = {}) {
  const catalog = options.catalog && typeof options.catalog === 'object' ? options.catalog : state.agentCatalog;
  const projectScope = typeof options.projectScope === 'string' && options.projectScope.trim()
    ? options.projectScope.trim()
    : currentAgentProjectScope();
  const models = Array.isArray(options.models) ? options.models : getAgentAvailableModelCatalog({ catalog });
  const preferredModelRef = getAgentPreferredModelRef({ catalog, models, projectScope });
  return [...models].sort((a, b) => compareAgentModelEntries(a, b, { catalog, preferredModelRef }));
}

function normalizeAgentProfile(raw = {}) {
  const providerId = normalizeAgentProviderId(raw?.provider_id || raw?.providerId || raw?.provider);
  const defaultModelRef = normalizeAgentModelRef(
    raw?.default_model_ref || raw?.defaultModelRef || raw?.defaultModel || '',
    providerId ? getAgentDefaultModelRef(providerId) : 'codex/default'
  );
  return {
    id: String(raw?.id || '').trim(),
    name: String(raw?.name || '').trim() || 'Untitled agent',
    role: String(raw?.role || 'operator').trim() || 'operator',
    provider_id: providerId || normalizeAgentProviderId(defaultModelRef.split('/')[0]) || 'codex',
    default_model_ref: defaultModelRef,
    default_project_scope: String(raw?.default_project_scope || raw?.defaultProjectScope || '').trim() || 'global',
    description: String(raw?.description || '').trim(),
    active: raw?.active !== false
  };
}

function applyAgentProfiles(rows) {
  state.agentProfiles = (Array.isArray(rows) ? rows : [])
    .map((row) => normalizeAgentProfile(row))
    .filter((row) => row.id);
  return state.agentProfiles;
}

function getAgentProfileById(profileId) {
  const id = String(profileId || '').trim();
  if (!id) return null;
  return state.agentProfiles.find((entry) => entry && entry.id === id) || null;
}

function getAgentProfileLabel(profileId) {
  const profile = getAgentProfileById(profileId);
  return profile ? profile.name : 'Any agent';
}

function resolveAgentProfileForRun(options = {}) {
  const providerId = normalizeAgentProviderId(options?.providerId || options?.provider_id);
  const projectScope = String(options?.projectScope || options?.project_scope || currentAgentProjectScope()).trim() || 'global';
  const modelRef = normalizeAgentModelRef(
    options?.modelRef || options?.model_ref || '',
    providerId ? getAgentDefaultModelRef(providerId) : 'codex/default'
  );
  const activeProfiles = (Array.isArray(state.agentProfiles) ? state.agentProfiles : [])
    .filter((profile) => profile && profile.active !== false);
  if (!activeProfiles.length) return '';

  const ranked = [...activeProfiles]
    .map((profile) => {
      const project = String(profile.default_project_scope || '').trim() || 'global';
      const profileProvider = normalizeAgentProviderId(profile.provider_id || profile.provider);
      const profileModelRef = normalizeAgentModelRef(profile.default_model_ref, '');
      return {
        profile,
        score: [
          project === projectScope ? 0 : 1,
          profileProvider && providerId && profileProvider === providerId ? 0 : 1,
          profileModelRef && modelRef && profileModelRef === modelRef ? 0 : 1,
          profileProvider ? 0 : 1,
          project === 'global' ? 1 : 0
        ]
      };
    })
    .sort((a, b) => {
      for (let index = 0; index < Math.max(a.score.length, b.score.length); index += 1) {
        const diff = (a.score[index] || 0) - (b.score[index] || 0);
        if (diff !== 0) return diff;
      }
      return String(a.profile.name || '').localeCompare(String(b.profile.name || ''), undefined, { sensitivity: 'base' });
    });
  return ranked[0]?.profile?.id || '';
}

// Column options for select fields
