function editTask(id) {
  if (!ensureWorkspaceRuntimeCanMutate()) return;
  const task = state.tasks.find(t => t.Id === id);
  if (!task) return;
  const planning = getTaskPlanning(task.Id, { create: false }) || normalizeTaskPlanningEntry({ taskId: task.Id }, task.Id);
  const milestone = getMilestoneById(planning.milestoneId);
  
  state.editingTaskId = id;
  
  document.getElementById('editTaskName').value = task['Task Name'] || '';
  document.getElementById('editAssignedTo').value = task['Assigned To'] || '';
  document.getElementById('editAsset').value = task.Link || '';
  
  // Set department dropdown value and update custom select display
  const deptValue = task['Pipeline Step'] || '';
  document.getElementById('editDept').value = deptValue;
  const editDeptCustom = document.getElementById('editDept').parentElement.querySelector('.custom-select');
  if (editDeptCustom) {
    const trigger = editDeptCustom.querySelector('.custom-select-trigger');
    const triggerText = trigger.querySelector('.custom-select-text');
    const triggerDot = trigger.querySelector('.color-dot');
    if (deptValue) {
      triggerText.textContent = deptValue;
      triggerDot.style.display = 'inline-block';
      triggerDot.style.background = getDeptColor(deptValue);
    } else {
      triggerText.textContent = 'Select Department';
      triggerDot.style.display = 'none';
    }
    // Mark selected option
    editDeptCustom.querySelectorAll('.custom-select-option').forEach(opt => {
      opt.classList.toggle('selected', opt.dataset.value === deptValue);
    });
  }
  
  const editStatusSelect = document.getElementById('editStatus');
  const currentStatus = task.Status || '';
  if (editStatusSelect && currentStatus) {
    const hasOption = Array.from(editStatusSelect.options).some((option) => option.value === currentStatus);
    if (!hasOption) {
      editStatusSelect.append(new Option(getStatusLabel(currentStatus) || currentStatus, currentStatus));
    }
  }
  document.getElementById('editStatus').value = currentStatus;
  document.getElementById('editStart').value = task.Start || '';
  document.getElementById('editEnd').value = task.End || '';
  document.getElementById('editDuration').value = task.Duration || '';
  document.getElementById('editETA').value = state.taskETAs[id] || '';
  document.getElementById('editNotes').value = task['Dept Prod Note'] || '';
  document.getElementById('editTargetStatus').value = task['Target Status Summary'] || '';
  document.getElementById('editAllocation').value = parseAllocation(task['% Allocation']);
  document.getElementById('editProjectStage').value = task['Project Stage'] || '';
  document.getElementById('editLocation').value = task.Location || '';
  document.getElementById('editDeadline').value = task.Deadline || '';
  document.getElementById('editPriority').value = planning.priority || 'medium';
  document.getElementById('editRiskLevel').value = planning.riskLevel || 'none';
  document.getElementById('editMilestone').value = milestone?.title || planning.milestoneId || '';
  document.getElementById('editReviewer').value = planning.reviewerId || '';
  document.getElementById('editApprover').value = planning.approverId || '';
  document.getElementById('editDeptEstimate').value = task['Dept Est'] || '';
  document.getElementById('editTotalWork').value = task['Total Work'] || '';
  document.getElementById('editAcceptanceCriteria').value = planning.acceptanceCriteria || '';
  
  // Update duration when dates change
  const updateDuration = () => {
    const start = document.getElementById('editStart').value;
    const end = document.getElementById('editEnd').value;
    document.getElementById('editDuration').value = calcBusinessDays(start, end);
  };
  
  document.getElementById('editStart').onchange = updateDuration;
  document.getElementById('editEnd').onchange = updateDuration;
  
  document.getElementById('editModal').classList.add('open');
  document.getElementById('editTaskName').focus();
}

function closeEditModal() {
  document.getElementById('editModal').classList.remove('open');
  state.editingTaskId = null;
  
  // Reopen Gantt if we were editing from there
  if (ganttState.editingFromGantt) {
    ganttState.editingFromGantt = false;
    renderGanttChart();
  }
}

function saveTaskEdit() {
  if (!ensureWorkspaceRuntimeCanMutate()) return;
  const task = state.tasks.find(t => t.Id === state.editingTaskId);
  if (!task) return;
  const planningBefore = capturePlanningSnapshot();

  const validation = validateEditTaskInput({
    taskName: document.getElementById('editTaskName').value,
    assignedTo: document.getElementById('editAssignedTo').value,
    asset: document.getElementById('editAsset').value,
    dept: document.getElementById('editDept').value,
    status: document.getElementById('editStatus').value,
    start: document.getElementById('editStart').value,
    end: document.getElementById('editEnd').value,
    notes: document.getElementById('editNotes').value,
    targetStatus: document.getElementById('editTargetStatus').value,
    allocation: document.getElementById('editAllocation').value,
    eta: document.getElementById('editETA').value
  });
  if (!validation.ok) {
    showToast(validation.message, 'error');
    return;
  }
  const formData = validation.data;
  
  const before = { ...task };
  const beforeEta = state.taskETAs[state.editingTaskId] || '';
  const afterPatch = {};
  
  task['Task Name'] = formData.taskName;
  task['Assigned To'] = formData.assignedTo;
  task.Link = formData.asset;
  task['Pipeline Step'] = formData.dept;
  task.Status = formData.status;
  task.Start = formData.start;
  task.End = formData.end;
  task.Duration = calcBusinessDays(formData.start, formData.end).toString();
  task['Dept Prod Note'] = formData.notes;
  task['Target Status Summary'] = formData.targetStatus;
  task['% Allocation'] = formData.allocation === '' ? '' : `${formData.allocation}%`;
  task['Project Stage'] = document.getElementById('editProjectStage')?.value || '';
  task.Location = document.getElementById('editLocation')?.value || '';
  task.Deadline = document.getElementById('editDeadline')?.value || '';
  task['Dept Est'] = document.getElementById('editDeptEstimate')?.value || '';
  task['Total Work'] = document.getElementById('editTotalWork')?.value || '';
  const planningChanged = applyTaskPlanningApiUpdates(task.Id, {
    priority: document.getElementById('editPriority')?.value || 'medium',
    riskLevel: document.getElementById('editRiskLevel')?.value || 'none',
    milestone: document.getElementById('editMilestone')?.value || '',
    reviewerId: document.getElementById('editReviewer')?.value || '',
    approverId: document.getElementById('editApprover')?.value || '',
    acceptanceCriteria: document.getElementById('editAcceptanceCriteria')?.value || ''
  });

  const eta = formData.eta;
  if (eta) {
    state.taskETAs[state.editingTaskId] = eta;
  } else {
    delete state.taskETAs[state.editingTaskId];
  }

  const taskFieldsChanged = diffTaskFields(before, task);
  const afterEta = state.taskETAs[state.editingTaskId] || '';
  const etaChanged = beforeEta !== afterEta;

  if (taskFieldsChanged.size > 0 || etaChanged) {
    const undoOps = [];
    const redoOps = [];

    if (taskFieldsChanged.size > 0) {
      const beforePatch = {};
      for (const field of taskFieldsChanged) {
        beforePatch[field] = before[field];
        afterPatch[field] = task[field];
      }
      undoOps.push({ op: 'task.update', taskId: task.Id, patch: beforePatch });
      redoOps.push({ op: 'task.update', taskId: task.Id, patch: afterPatch });
    }

    if (etaChanged) {
      undoOps.push({ op: 'eta.set', taskId: task.Id, value: beforeEta });
      redoOps.push({ op: 'eta.set', taskId: task.Id, value: afterEta });
    }

    if (planningChanged) {
      const planningAfter = capturePlanningSnapshot();
      if (planningSnapshotChanged(planningBefore, planningAfter)) {
        undoOps.push({ op: 'planning.replaceAll', ...planningBefore });
        redoOps.push({ op: 'planning.replaceAll', ...planningAfter });
      }
    }

    saveState({ undoOps, redoOps, label: 'Edit task' });
  } else if (planningChanged) {
    const planningAfter = capturePlanningSnapshot();
    if (planningSnapshotChanged(planningBefore, planningAfter)) {
      saveState({
        undoOps: [{ op: 'planning.replaceAll', ...planningBefore }],
        redoOps: [{ op: 'planning.replaceAll', ...planningAfter }],
        label: 'Edit task planning'
      });
    }
  }

  const fieldsChanged = new Set(taskFieldsChanged);
  if (etaChanged) fieldsChanged.add('__eta');
  const shotgridFieldsChanged = [...taskFieldsChanged].filter(f => SHOTGRID_PUSH_FIELD_SET.has(f));
  if (shotgridFieldsChanged.length > 0) markShotGridDirty(task.Id, shotgridFieldsChanged);
  if (fieldsChanged.size > 0) recordTaskFlash(task.Id, [...fieldsChanged]);
  
  closeEditModal();
  renderBoard();
  renderSprintList();
  populateFilters();
  if (Object.keys(afterPatch).length > 0) {
    queueLocalBrokerOperations(
      [{ type: 'update', taskId: task.Id, updates: afterPatch }],
      { source: 'ui-edit', quiet: true }
    );
  }
  showToast('Task saved');
}

// ============================================================================
// Quick Add Task (Kanban Column Click)
// ============================================================================

let activeQuickAddColumn = null;

function handleColumnQuickAdd(event, columnId) {
  // Only trigger if clicking directly on the column body (not on a card)
  if (event.target.closest('.card') || event.target.closest('.quick-add-form')) {
    return;
  }
  
  // Don't trigger if there's already an active quick-add in this column
  if (activeQuickAddColumn === columnId) return;
  
  // Close any existing quick-add
  closeQuickAdd();
  
  const columnBody = event.currentTarget;
  activeQuickAddColumn = columnId;
  
  // Get the default status for this column
  const column = columns.find(c => c.id === columnId);
  const defaultStatus = column?.statuses[0] || 'hld';
  
  // Get current filter values to pre-populate
  const assetFilter = document.getElementById('filterAsset')?.value || '';
  const artistFilter = document.getElementById('filterArtist')?.value || '';
  const deptFilter = document.getElementById('filterDept')?.value || '';
  
  // Also check spotlight multi-filters
  const spotlightFilters = state.spotlightFilters || { depts: [], artists: [], assets: [] };
  const prefilledAsset = assetFilter || (spotlightFilters.assets.length === 1 ? spotlightFilters.assets[0] : '');
  const prefilledArtist = artistFilter || (spotlightFilters.artists.length === 1 ? spotlightFilters.artists[0] : '');
  const prefilledDept = deptFilter || (spotlightFilters.depts.length === 1 ? spotlightFilters.depts[0] : '');
  
  // Create the quick-add form
  const quickAddHtml = `
    <div class="quick-add-form" data-column="${columnId}">
      <input type="text" 
             class="quick-add-input" 
             placeholder="Task name..." 
             onkeydown="handleQuickAddKeydown(event, '${columnId}', '${defaultStatus}', '${escapeJsString(prefilledAsset)}', '${escapeJsString(prefilledArtist)}', '${escapeJsString(prefilledDept)}')"
             onblur="handleQuickAddBlur(event)">
      <div class="quick-add-hints">
        ${prefilledAsset ? `<span class="quick-add-hint">${escapeHtml(prefilledAsset)}</span>` : ''}
        ${prefilledDept ? `<span class="quick-add-hint">${escapeHtml(prefilledDept)}</span>` : ''}
        ${prefilledArtist ? `<span class="quick-add-hint">${escapeHtml(prefilledArtist)}</span>` : ''}
        <span class="quick-add-hint-action">Enter to create · Esc to cancel</span>
      </div>
    </div>
  `;
  
  columnBody.insertAdjacentHTML('afterbegin', quickAddHtml);
  
  // Focus the input
  const input = columnBody.querySelector('.quick-add-input');
  if (input) {
    input.focus();
  }
}

function handleQuickAddKeydown(event, columnId, defaultStatus, prefilledAsset, prefilledArtist, prefilledDept) {
  if (event.key === 'Escape') {
    event.preventDefault();
    closeQuickAdd();
    return;
  }
  
  if (event.key === 'Enter') {
    event.preventDefault();
    const taskName = event.target.value.trim();
    
    if (!taskName) {
      closeQuickAdd();
      return;
    }
    
    // Create the task
    createQuickTask(taskName, columnId, defaultStatus, prefilledAsset, prefilledArtist, prefilledDept);
  }
}

function handleQuickAddBlur(event) {
  // Small delay to allow for click events on the form itself
  setTimeout(() => {
    // Check if focus moved to another element within the quick-add form
    const activeEl = document.activeElement;
    if (activeEl && activeEl.closest('.quick-add-form')) {
      return;
    }
    closeQuickAdd();
  }, 150);
}

function closeQuickAdd() {
  const existingForm = document.querySelector('.quick-add-form');
  if (existingForm) {
    existingForm.remove();
  }
  activeQuickAddColumn = null;
}

function createQuickTask(taskName, columnId, status, asset, artist, dept) {
  // If no asset is provided, we need at least something - use a placeholder or prompt
  if (!asset) {
    // Get the first available asset from the task list
    const assets = [...new Set(state.tasks.map(t => t.Link).filter(Boolean))];
    if (assets.length === 1) {
      asset = assets[0];
    } else {
      // Show toast and open full create modal instead
      closeQuickAdd();
      showToast('Select an asset filter first, or use New Task button', 'warning');
      return;
    }
  }
  
  // Generate task name if it looks like just a description (auto-prefix with dept)
  let finalTaskName = taskName;
  if (dept && !taskName.match(/^[A-Z]{2,}/)) {
    // If task name doesn't start with a dept abbreviation, try to generate one
    const generated = generateTaskName(asset, dept);
    if (generated) {
      finalTaskName = `${generated} - ${taskName}`;
    }
  }
  
  const insertIndex = state.tasks.length;
  const newTask = {
    Id: generateId(),
    __source: 'local',
    'Task Name': finalTaskName,
    'Assigned To': artist || '',
    Link: asset,
    'Pipeline Step': dept || '',
    Status: status,
    Start: '',
    End: '',
    Duration: '0',
    'Dept Prod Note': '',
    'Target Status Summary': 'ON TARGET',
    Project: resolveTaskProjectValue(),
    'Task Comments': '',
    'Project Stage': '',
    Location: '',
    Deadline: '',
    '% Allocation': '',
    'Dept Est': '',
    'Total Work': ''
  };

  saveState({
    undoOps: [{ op: 'task.remove', taskId: newTask.Id }],
    redoOps: [{ op: 'task.insert', index: insertIndex, task: cloneTaskForUndo(newTask) }],
    label: 'Quick create task'
  });
  
  state.tasks.push(newTask);
  
  closeQuickAdd();
  renderBoard();
  populateFilters();
  queueLocalBrokerOperations(
    [{ type: 'create', task: newTask }],
    { source: 'ui-quick-create', quiet: true }
  );
  showToast('Task created');
  
  // Select the new task
  state.selectedTaskId = newTask.Id;

  // Optional direct create sync (disabled by default; background sync service should handle creates).
  if (shouldDirectCreateSync()) {
    console.log('[uptospeed] Creating quick-add task in Flow Production Tracking…', newTask);
    createTaskInShotGrid(newTask);
  } else {
    console.log('[uptospeed] Created quick-add task locally; direct Flow Production Tracking create is disabled');
  }
}

